import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { api } from '@/lib/api';
import { useSites } from './useSites';
import type { MonitorCheck, Incident, AlertChannel, CreateAlertChannelInput } from '@pingwatch/shared';

export function useSiteDetail(siteId: string) {
  const queryClient = useQueryClient();
  const { sites, isLoading: isLoadingSites } = useSites();
  const site = sites.find((s) => s.id === siteId);

  const checksQuery = useQuery<MonitorCheck[]>({
    queryKey: ['site-checks', siteId],
    queryFn: () => api.getSiteChecks(siteId, 50),
    enabled: !!siteId,
    refetchInterval: 10000,
  });

  const incidentsQuery = useQuery<Incident[]>({
    queryKey: ['site-incidents', siteId],
    queryFn: () => api.getSiteIncidents(siteId),
    enabled: !!siteId,
    refetchInterval: 10000,
  });

  const channelsQuery = useQuery<AlertChannel[]>({
    queryKey: ['site-channels', siteId],
    queryFn: () => api.getAlertChannels(siteId),
    enabled: !!siteId,
  });

  const addChannelMutation = useMutation({
    mutationFn: (data: CreateAlertChannelInput) => api.createAlertChannel(data),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['site-channels', siteId] });
      queryClient.invalidateQueries({ queryKey: ['channels'] });
    },
  });

  const deleteChannelMutation = useMutation({
    mutationFn: (channelId: string) => api.deleteAlertChannel(channelId),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['site-channels', siteId] });
      queryClient.invalidateQueries({ queryKey: ['channels'] });
    },
  });

  const checks = checksQuery.data || [];
  const incidents = incidentsQuery.data || [];
  const activeIncident = incidents.find((inc) => !inc.resolved_at) || null;

  // Calculate Uptime % in last 24 hours & 7 days
  const now = Date.now();
  const oneDayAgo = now - 24 * 60 * 60 * 1000;
  const sevenDaysAgo = now - 7 * 24 * 60 * 60 * 1000;

  const checks24h = checks.filter((c) => new Date(c.checked_at).getTime() >= oneDayAgo);
  const upChecks24h = checks24h.filter((c) => c.is_up);
  const uptime24h = checks24h.length > 0
    ? Math.round((upChecks24h.length / checks24h.length) * 1000) / 10
    : site?.last_status === 'down' ? 0 : 100;

  const checks7d = checks.filter((c) => new Date(c.checked_at).getTime() >= sevenDaysAgo);
  const upChecks7d = checks7d.filter((c) => c.is_up);
  const uptime7d = checks7d.length > 0
    ? Math.round((upChecks7d.length / checks7d.length) * 1000) / 10
    : site?.last_status === 'down' ? 0 : 100;

  return {
    site,
    isLoading: isLoadingSites || checksQuery.isLoading,
    checks,
    incidents,
    activeIncident,
    uptime24h,
    uptime7d,
    channels: channelsQuery.data || [],
    isLoadingChannels: channelsQuery.isLoading,
    addChannel: addChannelMutation.mutateAsync,
    deleteChannel: deleteChannelMutation.mutateAsync,
  };
}
